let current='home',tabName='工作空间';
const $=s=>document.querySelector(s),icon=n=>`<i data-lucide="${n}"></i>`;
function icons(){lucide.createIcons()}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function closeModal(){$('#modal-bg').style.display='none'}function modal(html){$('#modal').innerHTML=`<button class="modal-close" aria-label="关闭" onclick="closeModal()">${icon('x')}</button>`+html;$('#modal-bg').style.display='grid';icons();$('#modal button').focus()}
function about(){modal('<h2 id="modal-title">全域运营 · 交互原型</h2><p>私域数字员工提供客户群发、运营统计、群聊查询和运营问答；抖音数字员工提供视频生成、直播监控和数据监控。</p><p>当前为本地示例，不连接业务服务、不发送消息。刷新页面会重置草案和查询状态。</p>')}
const info={home:['今日工作台','从一个具体需求开始，让数字员工帮你完成运营工作'],send:['客户群发','私域数字员工 / 向客户私聊发送 1 对 1 消息'],query:['运营统计','私域数字员工 / 客户增长、留存与触达效果'],groups:['群聊查询','私域数字员工 / 群聊、群主、成员与分组'],qa:['运营问答','私域数字员工 / 查找操作指引与问题依据'],video:['视频生成','抖音数字员工 / 从门店素材到创作方案'],live:['直播监控','抖音数字员工 / 画面巡检、问题诊断与跟进'],monitor:['数据监控','抖音数字员工 / 成交、核销与经营异常'],files:['成果库','查看当前会话中的群发草案和视频创作方案']};
function head(key){return `<div class="page-head"><div class="eyebrow">全域运营工作台 / ${['send','query','groups','qa'].includes(key)?'私域数字员工':key==='home'||key==='files'?'工作空间':'抖音数字员工'}</div><div class="title-row"><h1>${info[key][0]}</h1><span class="badge">演示模式</span></div><div class="desc">${info[key][1]}</div><div class="tabs">${['工作空间','执行记录'].map(t=>`<button onclick="switchTab('${t}')" class="${tabName===t?'active':''}">${t}</button>`).join('')}</div></div>`}
function navigate(key){current=info[key]?key:'home';document.querySelector('.mobile-nav').value=current;tabName='工作空间';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===current));document.querySelectorAll('[data-rail]').forEach(e=>e.classList.toggle('active',e.dataset.rail===(['send','query','groups','qa'].includes(current)?'send':['video','live','monitor'].includes(current)?'video':current)));render()}
function switchTab(t){tabName=t;render()}function render(){$('#main').innerHTML=head(current)+workspace();if(current==='video')renderVideoRight();else renderPrivateRight();icons()}
function table(cols,rows){return `<div class="table-scroll"><table class="table"><thead><tr>${cols.map(c=>'<th scope="col">'+c+'</th>').join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${cols.length}" class="empty-table">没有符合条件的示例记录，请调整筛选。</td></tr>`}</tbody></table></div>`}
function metrics(items){return `<div class="metric-grid">${items.map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('')}</div>`}
function workspace(){if(current==='video')return videoWorkspace();if(['send','query','groups','qa'].includes(current))return privateWorkspace();if(tabName==='执行记录')return `<div class="workspace"><h2>当前会话记录</h2>${renderPrivateLogs()}</div>`;if(current==='home')return homeWorkspace();if(current==='files')return filesWorkspace();if(current==='live')return `<div class="workspace">${metrics([['巡检直播间','3','演示监控状态'],['待处理问题','2','建议优先处理'],['本次巡检项','24','画面、商品、主播、运营']])}<h2>直播巡检</h2><div class="feature-box"><div class="field"><label for="liveUrl">直播链接或 room_id</label><input id="liveUrl" placeholder="粘贴需要巡检的抖音直播间"></div><button class="primary" onclick="inspectLive()">${icon('scan-eye')} 开始巡检</button></div>${table(['直播间','最近巡检','状态'],[['品牌 A · 滨江店','14:35','需关注'],['品牌 A · 城北店','14:34','监控中'],['品牌 A · 湖畔店','14:32','监控中']])}<h2>优先处理</h2><div class="feature-box"><h3>滨江店 · 活动适用条件展示不完整</h3><p>建议补充适用门店、有效期与使用条件，确保信息准确。</p><button class="secondary" onclick="toast('已记录示例跟进事项，未提交业务服务')">记录跟进事项</button></div></div>`;
return `<div class="workspace">${metrics([['成交金额','¥ 86,420','示例数据'],['核销金额','¥ 62,180','示例数据'],['短视频成交占比','28.4%','示例数据']])}<h2>门店经营监控</h2>${table(['门店','成交金额','核销金额','状态'],[['滨江店','¥ 38,240','¥ 27,860','监控中'],['城北店','¥ 29,680','¥ 21,240','监控中'],['湖畔店','¥ 18,500','¥ 13,080','需关注']])}<h2>异常提醒</h2><div class="feature-box"><h3>湖畔店 · 成交金额较前期下降 18%</h3><p>建议检查开播时长、商品权益与内容更新情况。波动原因需要进一步验证。</p></div><p class="empty-note">演示数据，尚未接入真实经营指标。</p></div>`}
function homeWorkspace(){return `<div class="private-work"><div class="welcome-block"><div class="eyebrow">YOUR DIGITAL TEAM</div><h2>今天，先处理哪件事？</h2><p>选择员工的工作能力，直接进入对应流程。</p></div><div class="home-employee"><div class="avatar">${icon('users-round')}</div><div><h3>私域数字员工</h3><p>面向企微客户与社群的日常运营</p></div><span class="badge">4 项能力</span></div><div class="home-grid">${[['send','send','客户群发','选员工、筛客户，先预览再确认'],['query','chart-no-axes-combined','运营统计','查增长、排行、留存和触达'],['groups','messages-square','群聊查询','找群聊，查看群主与群成员'],['qa','book-open-text','运营问答','查流程、找口径、定位问题依据']].map(([key,ic,title,desc])=>`<button class="home-capability" onclick="navigate('${key}')">${icon(ic)}<h3>${title}</h3><p>${desc}</p><span>进入工作空间 →</span></button>`).join('')}</div><div class="home-employee" style="margin-top:25px"><div class="avatar douyin">${icon('clapperboard')}</div><div><h3>抖音数字员工</h3><p>内容创作与门店经营支持</p></div><span class="badge">3 项能力</span></div><div class="home-grid douyin-grid">${[['video','clapperboard','视频生成','从素材到创作方案'],['live','scan-eye','直播监控','巡检画面与运营问题'],['monitor','chart-line','数据监控','关注成交与核销表现']].map(([key,ic,title,desc])=>`<button class="home-capability" onclick="navigate('${key}')">${icon(ic)}<h3>${title}</h3><p>${desc}</p><span>进入工作空间 →</span></button>`).join('')}</div><p class="empty-note">当前为功能原型。所有客户和群聊均为虚构示例，不会触发真实业务操作。</p></div>`}
function filesWorkspace(){let drafts=privateState.drafts;return `<div class="private-work"><div class="video-card"><h3>客户群发草案 · ${drafts.length} 份</h3>${drafts.length?table(['草案','目标客户','状态','操作'],drafts.map(d=>[esc(d.name),d.count+' 人',d.cancelled?'已取消草案':'待业务接入',`<button class="link" onclick="viewSendDraft('${d.id}')">查看 →</button>`])):'<p class="empty-note">还没有保存的草案。完成客户范围预览后，可在这里查看。</p><button class="primary" onclick="navigate(\'send\')">准备客户群发</button>'}</div><div class="video-card"><h3>视频创作方案</h3><p class="hint">${videoFlow.prompt?'当前会话已有创作描述，可返回视频工作空间继续。':'在视频生成工作空间确认创作方案后查看。'}</p><button class="secondary" onclick="navigate('video')">进入视频生成 →</button></div></div>`}
function inspectLive(){let value=$('#liveUrl').value.trim();if(!value){toast('请填写直播链接或 room_id');return}modal('<h2 id="modal-title">巡检任务预览</h2><p>'+esc(value)+'</p><p>巡检维度：画面质量、商品吸引力、主播专业度、投流运营能力。</p><div class="notice">演示环境，未连接真实直播间，未启动监控。</div>')}
$('#search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;let q=e.target.value.trim();if(!q)return;let found=Object.entries(info).filter(([key,[name,desc]])=>(name+desc).includes(q));modal('<h2 id="modal-title">功能搜索</h2><p>关键词：'+esc(q)+'</p>'+(found.length?found.map(([key,[name]])=>`<button class="nav" onclick="closeModal();navigate('${key}')">${name} →</button>`).join(''):'<p>没有匹配的功能。可搜索“客户”“统计”“群聊”“问答”或“视频”。</p>'))});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
